internal fun checklists(): List<Checklist> = listOf(
Checklist("home","البيت","صندوق إسعافات في مكان معروف، جاف، وسهل الوصول للبالغين.","وزارة الصحة: محتويات ومواصفات حقيبة الإسعافات الأولية","https://www.moh.gov.sa/Ministry/MediaCenter/Publications/Documents/Dose-fo-Awareness-2.pdf",listOf("حقيبة أو صندوق قوي يحمي المحتويات من الرطوبة، ومكانه معروف للبالغين.","قفازات استخدام مرة واحدة، وشاش وضمادات معقمة بأحجام مختلفة.","لواصق طبية وشريط تثبيت ولفافة ضاغطة وكمادات باردة.","محلول ملحي معقم لغسل العين أو الجروح، وميزان حرارة.","مقص صغير وملاقط ومسحات طبية، مع حفظها بعيدًا عن الأطفال.","قائمة بأرقام 997 و998 و937 وعنوان المنزل الواضح.","طفاية مناسبة وكاشف دخان يعمل ومخرج إخلاء غير محجوب.","الأدوية الشخصية الموصوفة محفوظة وفق ملصقها، خارج متناول الأطفال.","تاريخ صلاحية المحتويات ومراجعتها بعد الاستخدام وكل 12 شهرًا.","تخزين المنظفات والأدوية والبطاريات والأدوات الحادة في مكان مقفل.")),
Checklist("car","السيارة","احتفظ بحقيبة الرعاية في مكان ثابت، ولا تترك أدوية حساسة للحرارة داخل السيارة.","وزارة الصحة: مواصفات حقيبة الإسعافات الأولية","https://www.moh.gov.sa/Ministry/MediaCenter/Publications/Documents/Dose-fo-Awareness-2.pdf",listOf("حقيبة إسعافات أولية: قفازات، شاش، ضمادات، شريط لاصق، ومقص.","كمادات باردة فورية ومحلول ملحي صغير وضمادات لاصقة.","سترة عاكسة ومثلث تحذير يوضعان من مكان آمن وبحسب أنظمة الطريق.","مصباح يدوي وبطاريات احتياطية وشاحن متنقل مشحون.","ماء للشرب للطوارئ، مع استبداله دوريًا وعدم تركه حتى يتلف بالحرارة.","أرقام 997 للإسعاف و993 للمرور و996 لأمن الطرق محفوظة بالهاتف.","معلومات الحساسية والأمراض والأدوية المهمة مع أحد الركاب أو في الهاتف.","مراجعة صلاحية الحقيبة بعد كل استخدام وبشكل دوري.")),
Checklist("school","المدرسة","على إدارة المدرسة تجهيز نقطة إسعاف واضحة، وتحديد مسؤولين مدربين وخطة إخلاء.","وزارة التعليم: الشؤون الصحية المدرسية والأدلة الصحية","https://www.moe.gov.sa/ar/education/general-education/schoolhealth",listOf("حقيبة أو صندوق إسعافات أولية مجهز ويمكن للموظفين الوصول إليه بسرعة.","قفازات، شاش معقم، ضمادات، شريط طبي، كمادات باردة، ومقياس حرارة.","أرقام الطوارئ وموقع المدرسة وعنوان بوابة دخول سيارة الإسعاف معروض للموظفين.","تحديد الموظف/الموجه الصحي المسؤول وبديله، وتحديث التدريب والإجراءات.","خطة واضحة للاتصال بولي الأمر والإخلاء وتسليم المصاب للمسعفين.","سجل وصول آمن ومحدود للمعلومات الصحية والحساسيات وخطط الرعاية الفردية.","الأدوية الموصوفة للطلاب محفوظة ومُدارة فقط وفق سياسة المدرسة وموافقة ولي الأمر.","مخارج الطوارئ خالية، وطفايات الحريق وإنذارات الدخان مفحوصة.","مراجعة الصندوق بعد كل استخدام واستبدال الناقص والمنتهي.")),
Checklist("cabin","الاستراحة","اجمع بين حقيبة إسعاف منزلية، وفحص مسبق للمسبح والغاز والإنذار.","وزارة الصحة: الإصابات المنزلية","https://www.moh.gov.sa/awarenessplateform/firstaid/pages/homeinjuries.aspx",listOf("حقيبة إسعافات أولية كاملة في مكان واضح وسهل الوصول.","طفاية حريق صالحة وكاشف دخان، ومعرفة كل الموجودين بمخارج المكان.","رقم الموقع/العنوان الوطني وبوابة الدخول جاهزان لمشاركتهما مع الإسعاف.","إن وجد مسبح: مراقبة مباشرة للأطفال، وسياج/بوابة تمنع دخولهم دون إشراف.","فحص توصيلات الغاز، وإبعاد مصادر اللهب، ومعرفة طريقة الإخلاء.","ماء شرب ومصباح يدوي وهاتف مشحون وشاحن متنقل.","تخزين الأدوية والمنظفات والأدوات الحادة بعيدًا عن الأطفال.","حفظ موقع أقرب مركز صحي وطريق الوصول إليه.")),
Checklist("camping","التخييم والبر","خطط للتغطية والاتصال والموقع قبل الخروج؛ لا تعتمد على وجود شبكة أو متجر قريب.","وزارة الصحة: التوعية الإسعافية","https://www.moh.gov.sa/awarenessplateform/firstaid/pages/default.aspx",listOf("حقيبة إسعاف صغيرة داخل كيس مقاوم للماء، مع شاش وقفازات وضمادات ومقص.","ماء شرب كافٍ وواقي شمس وقبعة وملابس مناسبة للطقس.","طارد حشرات وملاقط وأداة إضاءة، مع استخدام كل منتج حسب ملصقه.","بطارية متنقلة مشحونة وخريطة أو إحداثيات الموقع محفوظة دون اتصال.","مشاركة خط السير والموعد المتوقع للعودة مع شخص موثوق.","وسيلة تواصل بديلة وتجهيز أرقام الطوارئ 997 و998 و996.","بطانية عاكسة/حرارية وملابس إضافية وماء احتياطي بالمركبة.","عدم إشعال الفحم أو المولد في خيمة أو مقطورة أو مكان مغلق.","فحص الحقيبة بعد الرحلة وتعويض المواد المستخدمة.")),
Checklist("travel","السفر","استعد للأمراض المزمنة والحساسيات واحتياجات الأطفال قبل موعد السفر.","وزارة الصحة: صحة المسافر","https://www.moh.gov.sa/awarenessplateform/seasonalandfestivalhealth/pages/healthytravel.aspx",listOf("قائمة الأدوية والحساسيات والتشخيصات المهمة وأرقام التواصل للطوارئ.","الأدوية الموصوفة بكمية تكفي الرحلة، في عبواتها الأصلية وحقيبة اليد حسب شروط الناقل.","حقيبة إسعافات أولية صغيرة، ومواد تطهير، وكمامات احتياطية.","واقي شمس وطارد حشرات وأدوات النظافة الشخصية حسب الوجهة.","نسخة من الوصفات/التقارير الضرورية ووثائق التأمين الصحي.","التحقق من رقم الإسعاف والجهات المحلية في بلد الوجهة.","التحقق من اللقاحات والاشتراطات الصحية؛ واستشارة الطبيب قبل 4–6 أسابيع عند الحاجة.","شاحن متنقل وماء وأرقام التواصل وموقع السكن محفوظة دون اتصال."))
)
